/**
 * «Термінал Доглядача» in Foundry: the HTML terminal's four generators (Справа, Подорож, Натхнення, Битви).
 * The generators are the HTML terminal's own code (rules/terminal.mjs, generated by tools/port_terminal.py);
 * this window draws them, keeps the results (per user) and sends them to chat. «Битви» can also create the
 * enemies, place their tokens and start a combat (terminal-battle.mjs).
 */
import { createTerminal } from "../rules/terminal.mjs";
import { createBattle } from "./terminal-battle.mjs";
import { postChat } from "./chat.mjs";
import {
  TABLE_CARDS, battleChat, blankTerminal, buildTerminalView, caseChat, runTable, tableChat, travelChat,
} from "./terminal-view.mjs";

const { ApplicationV2, HandlebarsApplicationMixin } = foundry.applications.api;
const FLAG = "terminal";
const CONFIRM_MS = 3000;
const clone = (o) => (o == null ? o : JSON.parse(JSON.stringify(o)));

let OPEN = null;
/** Open the terminal (Доглядач only) */
export function openTerminal() {
  if (!game.user.isGM) return ui.notifications.warn("Термінал — для Доглядача.");
  OPEN ??= new TerminalApp();
  OPEN.render({ force: true });
  return OPEN;
}

class TerminalApp extends HandlebarsApplicationMixin(ApplicationV2) {
  static DEFAULT_OPTIONS = {
    id: "pust-terminal",
    classes: ["wastelanders", "pust-terminal-app"],
    position: { width: 860, height: 820 },
    window: { title: "Термінал Доглядача", icon: "fa-solid fa-terminal", resizable: true },
    actions: {
      termTab: TerminalApp.#on((app, t) => { app.st.tab = t.dataset.tab; }),
      caseDiff: TerminalApp.#on((app, t) => { app.st.case.diff = t.dataset.diff; if (app.st.case.cs) app.st.case.cs = clone(app.T.case.setDifficulty(t.dataset.diff)); else app.T.case.setDifficulty(t.dataset.diff); }),
      caseGen: TerminalApp.#on((app) => { app.st.case.cs = clone(app.T.case.generate(app.st.case.diff)); }),
      caseReroll: TerminalApp.#on((app, t) => { app.st.case.cs = clone(app.T.case.reroll(t.dataset.k)); }),
      travelType: TerminalApp.#on((app, t) => { app.st.travel.type = t.dataset.type; }),
      travelLuck: TerminalApp.#on((app, t) => { app.st.travel.luck = Number(t.dataset.luck); }),
      travelGen: TerminalApp.#on((app) => { Object.assign(app.st.travel, app.T.travel.generate(app.st.travel.type, app.st.travel.luck)); }),
      travelKinds: TerminalApp.#on((app, t) => app.#travelKinds(+t.dataset.i)),
      travelBattle: TerminalApp.#on((app, t) => app.#travelBattle(+t.dataset.i)),
      tableGen: TerminalApp.#on((app, t) => {
        const card = TABLE_CARDS.find((c) => c.id === t.dataset.card);
        app.st.tables.out[card.id] = runTable(app.T, card, app.st.tables.sel);
      }),
      battleGen: TerminalApp.#on((app) => app.#battle((B) => B.generate(app.st.battle.difficulty, app.st.battle.kinds), true)),
      battleScene: TerminalApp.#on((app, t) => app.#battle((B) => B.rollScene(t.dataset.kind))),
      battleReward: TerminalApp.#on((app) => app.#battle((B) => B.rollReward())),
      battleFold: TerminalApp.#on((app) => { app.ui.foldAll = !app.ui.foldAll; }),
      battleClear: TerminalApp.#on((app, t) => {
        if (!TerminalApp.#armed(t)) return false;
        app.st.battle.state = null; app.st.battle.names = [];
        app.T = null; // a fresh generator: the cleared battle is gone from it too
      }),
      battleCreate: TerminalApp.#onCreate,
      toChat: TerminalApp.#onChat,
      die: TerminalApp.#onDie,
    },
  };

  static PARTS = { main: { template: "systems/wastelanders-dev/templates/apps/terminal.hbs", scrollable: [".pust-term-body"] } };

  /** UI state not saved: folded enemy cards */
  ui = { foldAll: false };

  /** The saved terminal (per user) */
  get st() {
    this._st ??= foundry.utils.mergeObject(blankTerminal(), clone(game.user.getFlag(game.system.id, FLAG)) || {}, { inplace: false });
    return this._st;
  }

  /** The generators, with the saved results loaded into them */
  get T() {
    if (!this._T) {
      const T = createTerminal({ toast: (m) => ui.notifications.info(m), icon: (n) => `<i class="pust-pi pi-${n}"></i>` });
      const st = this.st;
      T.case.setDifficulty(st.case.diff);
      if (st.case.cs) T.case.set(clone(st.case.cs));
      T.battle.setDifficulty(st.battle.difficulty);
      T.battle.setKinds(st.battle.kinds);
      if (st.battle.state) T.battle.restore(clone(st.battle.state));
      this._T = T;
    }
    return this._T;
  }
  set T(v) {
    this._T = v;
  }

  #saveTimer = null;
  save() {
    clearTimeout(this.#saveTimer);
    this.#saveTimer = setTimeout(() => game.user.setFlag(game.system.id, FLAG, clone(this.st)), 300);
  }

  /** A handler that changes the state, then saves and redraws (return false to skip) */
  static #on(fn) {
    return async function (event, target) {
      if ((await fn(this, target, event)) === false) return;
      this.save();
      this.render();
    };
  }

  static #armed(target) {
    if (target.classList.contains("armed")) return true;
    target.classList.add("armed");
    ui.notifications.info("Натисни ще раз, щоб підтвердити.");
    setTimeout(() => target.classList.remove("armed"), CONFIRM_MS);
    return false;
  }

  #battle(fn, fresh = false) {
    const B = this.T.battle;
    B.setDifficulty(this.st.battle.difficulty);
    B.setKinds(this.st.battle.kinds);
    if (fresh && !this.st.battle.kinds.length) return ui.notifications.warn("Обери щонайменше один вид супротивників.");
    const s = fn(B);
    if (fresh) this.st.battle.names = [];
    this.st.battle.state = clone({ ...s, names: undefined });
  }

  /* ---------- travel battles: reroll the kinds, or move the battle to «Битви» ---------- */

  #travelSection(i) {
    const div = document.createElement("div");
    div.innerHTML = this.st.travel.additional;
    return { div, sec: div.querySelectorAll(".battle-encounter")[i] };
  }

  #travelKinds(i) {
    const { div, sec } = this.#travelSection(i);
    const span = sec?.querySelector(".tvb-rnd");
    if (!span) return false;
    const ks = this.T.travel.kindsRoll((span.dataset.kinds || "").split(",").filter(Boolean));
    span.dataset.kinds = ks.join(",");
    span.innerHTML = this.T.travel.randomText(ks);
    this.st.travel.additional = div.innerHTML;
  }

  #travelBattle(i) {
    const { sec } = this.#travelSection(i);
    const span = sec?.querySelector(".tvb");
    if (!span) return false;
    const place = sec.querySelector(".tv-place")?.textContent || "";
    const spec = span.dataset.kinds
      ? { diff: span.dataset.diff, kinds: span.dataset.kinds.split(",").filter(Boolean), place }
      : { diff: span.dataset.diff, idx: +span.dataset.idx, place };
    const s = this.T.battle.fromTravel(spec);
    if (!s) return ui.notifications.warn("Не вдалося зібрати цю битву."), false;
    this.st.battle.difficulty = s.difficulty;
    this.st.battle.names = s.names || [];
    this.st.battle.state = clone({ ...s, names: undefined });
    this.st.tab = "battle";
    ui.notifications.info("Битву з подорожі перенесено на вкладку «Битви».");
  }

  /* ---------- buttons with their own work ---------- */

  static async #onCreate(event, target) {
    target.disabled = true;
    try {
      await createBattle(this.T, this.st, target.dataset.mode);
    } finally {
      target.disabled = false;
    }
  }

  static async #onChat(event, target) {
    const st = this.st;
    const html = { case: () => caseChat(st), travel: () => travelChat(st), table: () => tableChat(st, target.dataset.card), battle: () => battleChat(this.T, st) }[target.dataset.what]?.();
    if (!html) return;
    const data = { content: html, speaker: ChatMessage.getSpeaker({ alias: "Термінал Доглядача" }) };
    await postChat(data);
  }

  /** A die in the results («2d6»): rolled by Foundry and posted to chat */
  static async #onDie(event, target) {
    const expr = target.dataset.dice;
    if (!expr) return;
    const roll = await new Roll(expr.replace(/^d/, "1d")).evaluate();
    await roll.toMessage({ speaker: ChatMessage.getSpeaker({ alias: "Термінал Доглядача" }), flavor: expr }); // the chat's mode menu by default
  }

  /* ---------- drawing ---------- */

  async _prepareContext() {
    return { v: buildTerminalView(this.T, this.st, this.ui) };
  }

  _onRender(context, options) {
    super._onRender(context, options);
    const root = this.element;
    // dice from the generators' HTML: <button class="die" data-dice="2d6">
    root.querySelectorAll("button.die").forEach((b) => { b.type = "button"; b.dataset.action = "die"; b.title = `Кинути ${b.dataset.dice}`; });
    // travel battles: «Перекинути види» and «Створити битву» (the HTML terminal's tvEnhance)
    root.querySelectorAll(".pust-travel .battle-encounter").forEach((sec, i) => {
      const span = sec.querySelector(".tvb");
      if (!span) return;
      const btns = document.createElement("div");
      btns.className = "pust-tvb-actions";
      btns.innerHTML = (span.classList.contains("tvb-rnd")
        ? `<button type="button" data-action="travelKinds" data-i="${i}" title="Перекинути випадкову битву: інші види супротивників"><i class="fa-solid fa-rotate"></i> Інші види</button>`
        : "")
        + `<button type="button" class="pust-term-go" data-action="travelBattle" data-i="${i}" title="Перенести битву й місце на вкладку «Битви»"><i class="fa-solid fa-skull"></i> Створити битву</button>`
        + `<span class="pust-sub">${span.classList.contains("tvb-rnd") ? "Склад супротивників кинеться за правилами генератора битв." : "Кількість супротивників кинеться за описом битви."} Місце піде у вкладку «Битви».</span>`;
      sec.append(btns);
    });
    // selects and checkboxes of the tabs
    root.querySelectorAll("[data-k]").forEach((el) => el.addEventListener("change", () => {
      const k = el.dataset.k;
      if (k.startsWith("tables.")) this.st.tables.sel[k.slice(7)] = el.value;
      else if (k === "battle.difficulty") this.st.battle.difficulty = el.value;
      else if (k === "battle.kind") {
        const ks = this.st.battle.kinds.filter((x) => x !== el.value);
        if (el.checked) ks.push(el.value);
        this.st.battle.kinds = this.T.battle.kinds().map((x) => x.key).filter((x) => ks.includes(x));
      }
      this.save();
      this.render();
    }));
  }

  _onClose(options) {
    super._onClose(options);
    clearTimeout(this.#saveTimer);
    game.user.setFlag(game.system.id, FLAG, clone(this.st));
  }
}
